package com.hrm.gui;
import com.hrm.service.*;import javax.swing.*;import java.awt.*;import java.time.LocalDate;
public class HRHistoryPanel extends JPanel{private final JTable t=Ui.table(new String[]{"Mã NV","Họ tên","Sự kiện","Ngày","Mô tả"});private final JComboBox<String> y=new JComboBox<>(new String[]{"Tất cả 5 năm","2022","2023","2024","2025","2026"});private final JTextField q=new JTextField(18);private final JButton penalty=Ui.btn("Ghi phạt / trừ lương");public HRHistoryPanel(){setLayout(new BorderLayout(8,8));add(Ui.top("Sự kiện nhân sự - thưởng, phạt, nghỉ, thăng chức"),BorderLayout.NORTH);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(new JLabel("Tìm NV:"));b.add(q);b.add(new JLabel("Năm:"));b.add(y);b.add(penalty);add(b,BorderLayout.SOUTH);add(new JScrollPane(t),BorderLayout.CENTER);Runnable load=()->{try{Ui.fill(t,new HRHistoryService().find(yearValue(),q.getText().trim()));}catch(Exception e){Ui.error(this,e);}};y.addActionListener(e->load.run());q.addActionListener(e->load.run());penalty.addActionListener(e->showPenalty());load.run();}private int yearValue(){String v=(String)y.getSelectedItem();return "Tất cả 5 năm".equals(v)?0:Integer.parseInt(v);}private void showPenalty(){JPanel f=new JPanel(new GridLayout(0,2,8,8));JTextField code=new JTextField(),amount=new JTextField("500000"),reason=new JTextField("Nghỉ quá số ngày quy định");f.add(new JLabel("Mã NV:"));f.add(code);f.add(new JLabel("Số tiền trừ:"));f.add(amount);f.add(new JLabel("Lý do:"));f.add(reason);f.add(new JLabel("Ngày:"));f.add(new JTextField(LocalDate.now().toString()));int ok=JOptionPane.showConfirmDialog(this,f,"Ghi phạt / trừ lương",JOptionPane.OK_CANCEL_OPTION);if(ok!=JOptionPane.OK_OPTION)return;try{int id=Integer.parseInt(code.getText().trim().toUpperCase().replace("NV",""));double a=Double.parseDouble(amount.getText().trim());String rs=reason.getText().trim();new DisciplineService().add(id,a,rs,LocalDate.now());JOptionPane.showMessageDialog(this,"Đã ghi khoản phạt. Khi tạo phiếu lương, khoản này sẽ được cộng vào Khấu trừ.");}catch(Exception e){Ui.error(this,e);}}}
